  "math-block": "import { Button, MathBlock, RotateCcw } from \"@nessa-ui/react\"\n\nfunction matches(query: string, values: string[]) {\n  const q = query.trim().toLowerCase();\n  return !q || values.some((value) => value.toLowerCase().includes(q));\n}\n\nexport function MathBlockDemo() {\n  const tex = String.raw`\\text{sim}(q, d) = \\frac{q \\cdot d}{\\lVert q \\rVert \\, \\lVert d \\rVert}`;\n  const [shown, setShown] = React.useState(tex);\n  const [run, setRun] = React.useState(0);\n\n  React.useEffect(() => {\n    if (window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches) {\n      setShown(tex);\n      return;\n    }\n    let i = 0;\n    setShown(\"\");\n    const id = window.setInterval(() => {\n      i += 2;\n      setShown(tex.slice(0, i));\n      if (i >= tex.length) window.clearInterval(id);\n    }, 45);\n    return () => window.clearInterval(id);\n  }, [tex, run]);\n\n  return (\n    <div className=\"flex w-full flex-col items-center gap-4\">\n      <MathBlock tex={shown} />\n      <Button variant=\"outline\" size=\"sm\" onClick={() => setRun((n) => n + 1)}>\n        <RotateCcw aria-hidden=\"true\" />\n        Replay\n      </Button>\n    </div>\n  );\n}\n\n<MathBlockDemo />",
